USE biz_alliance_config;
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (18, 'poco-knowledge-dev.yml', 'DEFAULT_GROUP', '# 数据源\nspring:\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      driver-class-name: com.mysql.cj.jdbc.Driver\n      username: ${MYSQL_USER:root}\n      password: ${MYSQL_PWD:root}\n      url: jdbc:mysql://${MYSQL_HOST:poco-mysql}:${MYSQL_PORT:3306}/${MYSQL_DB:biz_alliance_ai}?characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=false&useJDBCCompliantTimezoneShift=true&useLegacyDatetimeCode=false&serverTimezone=GMT%2B8&allowMultiQueries=true&allowPublicKeyRetrieval=true\n\n# AI 相关配置\npig:\n  ai:\n    qdrant:\n      host: 127.0.0.1\n      port: 6334\n      use-tls: false\n    risk-control: # 风控\n      enabled: true\n      no-limit-usernames: # 不受限制的用户名\n        - admin\n    show-log: true\n\nliteflow:\n  rule-source: rules/*-rule.xml\n  print-banner: false\n  print-execution-log: false\n  enable: true\n\n', 'd62ceeaab01356d79f5691f3457c4da1', '2024-04-19 14:59:10', '2024-10-13 10:58:27', 'nacos', '0:0:0:0:0:0:0:1', '', '', '知识库模块配置属性', '', '', 'yaml', '', '');

